// Reading engine (pure core): validation, server-side draw, crisis
// pre-check, prompt building, summary parsing, and SSE streaming.
// Workers AI and D1 stay at the edges (routes) so everything here is
// unit-testable.
import type { CardView } from "../db/tarot-store";

export const TOPICS = ["love", "career", "money", "health", "general"] as const;
export type Topic = (typeof TOPICS)[number];

export function isTopic(value: unknown): value is Topic {
  return typeof value === "string" && (TOPICS as readonly string[]).includes(value);
}

export function isLang(value: unknown): value is "th" | "en" {
  return value === "th" || value === "en";
}

/** Trimmed question, or null when it must be rejected. Max 300 chars
 *  (design board counter "{{count}}/300"), non-empty, no HTML tags
 *  (everything is escaped on render anyway). */
export function cleanQuestion(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  const question = raw.trim().replace(/\s+/g, " ");
  if (question.length < 1 || question.length > 300) return null;
  if (/<[a-zA-Z][^>]*>/.test(question)) return null;
  return question;
}

function randomValues(count: number): number[] {
  const buf = new Uint32Array(count);
  crypto.getRandomValues(buf);
  return [...buf];
}

export type DrawnCard = { id: number; reversed: boolean };

/** Three unique cards 0..77, 25% reversed each, server-side. */
export function drawReadingCards(): DrawnCard[] {
  const deck = Array.from({ length: 78 }, (_, i) => i);
  const rand = randomValues(6);
  // Fisher-Yates head: draw 3 without bias.
  for (let i = 0; i < 3; i++) {
    const j = i + (rand[i] % (78 - i));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return [0, 1, 2].map((k) => ({
    id: deck[k],
    reversed: rand[3 + k] % 100 < 25,
  }));
}

// --- Crisis pre-check (runs before quota/draw; a hit costs nothing) ---

const CRISIS_PATTERNS: { lang: "th" | "en"; re: RegExp }[] = [
  { lang: "th", re: /\u0e44\u0e21\u0e48\u0e2d\u0e22\u0e32\u0e01\u0e2d\u0e22\u0e39\u0e48\u0e41\u0e25\u0e49\u0e27|\u0e2d\u0e22\u0e32\u0e01\u0e2b\u0e32\u0e22\u0e44\u0e1b|\u0e08\u0e1a\u0e0a\u0e35\u0e27\u0e34\u0e15|\u0e01\u0e34\u0e19\u0e22\u0e32\u0e15\u0e32\u0e22|\u0e42\u0e14\u0e14\u0e15\u0e36\u0e01|\u0e44\u0e21\u0e48\u0e2d\u0e22\u0e32\u0e01\u0e21\u0e35\u0e0a\u0e35\u0e27\u0e34\u0e15\u0e2d\u0e22\u0e39\u0e48/ },
  { lang: "en", re: /suicid|\bkill (myself|me)\b|self[-\s]?harm|end (my|this) life|hurt(ing)? myself|cutting myself/i },
  { lang: "en", re: /want to die|end it all|no (reason|point) (to|in) liv|better off dead|jump off|overdose|hang myself|wish I (was|were) dead/i },
  { lang: "en", re: /\babuse[ds]?\b|\bassault(ed)?\b|domestic violence|rape[ds]?\b/i },
  { lang: "th", re: /\u0e06\u0e48\u0e32\u0e15\u0e31\u0e27\u0e15\u0e32\u0e22|\u0e2d\u0e22\u0e32\u0e01\u0e15\u0e32\u0e22|\u0e44\u0e21\u0e48\u0e2d\u0e22\u0e32\u0e01\u0e21\u0e35\u0e0a\u0e35\u0e27\u0e34\u0e15|\u0e17\u0e33\u0e23\u0e49\u0e32\u0e22\u0e15\u0e31\u0e27\u0e40\u0e2d\u0e07|\u0e01\u0e23\u0e35\u0e14\u0e41\u0e02\u0e19/ },
  { lang: "th", re: /\u0e16\u0e39\u0e01\u0e17\u0e33\u0e23\u0e49\u0e32\u0e22|\u0e16\u0e39\u0e01\u0e02\u0e48\u0e21\u0e02\u0e37\u0e19|\u0e02\u0e48\u0e21\u0e02\u0e37\u0e19|\u0e17\u0e32\u0e23\u0e38\u0e13|\u0e04\u0e27\u0e32\u0e21\u0e23\u0e38\u0e19\u0e41\u0e23\u0e07\u0e43\u0e19\u0e04\u0e23\u0e2d\u0e1a\u0e04\u0e23\u0e31\u0e27|\u0e25\u0e48\u0e27\u0e07\u0e25\u0e30\u0e40\u0e21\u0e34\u0e14/ },
];

/** True when the question signals self-harm, suicide, abuse, or crisis. */
export function isCrisisQuestion(question: string): boolean {
  return CRISIS_PATTERNS.some((p) => p.re.test(question));
}

/**
 * Borderline vocabulary that earns a model double-check (SPEC §10.4
 * keywords + small classifier). Deliberately broad — the classifier
 * makes the final call, and it fails open so borderline-but-benign
 * questions still get readings.
 */
const CRISIS_WATCH = /die|death|kill|hurt|harm|hopeless|worthless|pointless|give up|can'?t go on|end this pain|\u0e15\u0e32\u0e22|\u0e2a\u0e34\u0e49\u0e19\u0e2b\u0e27\u0e31\u0e07|\u0e17\u0e23\u0e21\u0e32\u0e19|\u0e1b\u0e27\u0e14\u0e23\u0e49\u0e32\u0e27/i;

export function crisisWatchHit(question: string): boolean {
  return CRISIS_WATCH.test(question);
}

/**
 * Keyword topics for free-typed questions. The client only sends a
 * topic when the user taps a suggestion chip; typed questions arrive
 * as "general", which would miscategorise e.g. "will i be rich?"
 * under General instead of Money. First match wins in love, money,
 * career, health order (love first so "wedding job" keeps the
 * wedding). An explicit non-general chip choice is never overridden.
 */
const TOPIC_PATTERNS: { topic: Topic; re: RegExp }[] = [
  { topic: "love", re: /love|crush|relationship|partner|boyfriend|girlfriend|husband|wife|marri|divorce|dating|breakup|cheat|romance|affair|\u0e23\u0e31\u0e01|\u0e41\u0e1f\u0e19|\u0e41\u0e15\u0e48\u0e07\u0e07\u0e32\u0e19|\u0e40\u0e25\u0e34\u0e01|\u0e2a\u0e32\u0e21\u0e35|\u0e20\u0e23\u0e23\u0e22\u0e32|\u0e2b\u0e22\u0e48\u0e32/i },
  { topic: "money", re: /\brich\b|riches|wealth|money|financ|salary|incomes?|debt|invest|lottery|paycheck|bankrupt|loans?|\u0e23\u0e27\u0e22|\u0e40\u0e07\u0e34\u0e19|\u0e2b\u0e19\u0e35\u0e49|\u0e25\u0e07\u0e17\u0e38\u0e19|\u0e23\u0e32\u0e22\u0e44\u0e14\u0e49|\u0e2b\u0e27\u0e22/i },
  { topic: "career", re: /\bjob\b|jobless|career|boss|promotion|interview|resign|fired|colleague|business|compan(y|ies)|workplace|unemploy|\u0e07\u0e32\u0e19|\u0e2d\u0e32\u0e0a\u0e35\u0e1e|\u0e40\u0e08\u0e49\u0e32\u0e19\u0e32\u0e22|\u0e1a\u0e23\u0e34\u0e29\u0e31\u0e17|\u0e2a\u0e21\u0e31\u0e04\u0e23\u0e07\u0e32\u0e19|\u0e2a\u0e31\u0e21\u0e20\u0e32\u0e29\u0e13\u0e4c|\u0e40\u0e25\u0e37\u0e48\u0e2d\u0e19\u0e15\u0e33\u0e41\u0e2b\u0e19\u0e48\u0e07|\u0e15\u0e01\u0e07\u0e32\u0e19|\u0e25\u0e32\u0e2d\u0e2d\u0e01/i },
  { topic: "health", re: /health|stress|sick|illness|sleep|insomnia|doctor|hospital|anxi|depress|tired|\u0e2a\u0e38\u0e02\u0e20\u0e32\u0e1e|\u0e40\u0e04\u0e23\u0e35\u0e22\u0e14|\u0e1b\u0e48\u0e27\u0e22|\u0e19\u0e2d\u0e19\u0e44\u0e21\u0e48\u0e2b\u0e25\u0e31\u0e1a|\u0e2b\u0e21\u0e2d|\u0e42\u0e23\u0e07\u0e1e\u0e22\u0e32\u0e1a\u0e32\u0e25|\u0e27\u0e34\u0e15\u0e01|\u0e0b\u0e36\u0e21\u0e40\u0e28\u0e23\u0e49\u0e32|\u0e40\u0e2b\u0e19\u0e37\u0e48\u0e2d\u0e22|\u0e1b\u0e27\u0e14/i },
];

/**
 * Deck questions ("สำรับเทวาลัยเข้ากันไหม", "should I buy this deck")
 * must stay "general": Thai ใช้งาน (to use) contains งาน (work), so
 * without this guard every deck-use question miscategorises as career
 * and drags the reading into work topics.
 */
const DECK_RE = /สำรับ|\bdeck\b|ทาโรต์|tarot/i;

/** Best-guess topic from question wording, "general" when nothing hits. */
export function guessTopic(question: string): Topic {
  if (DECK_RE.test(question)) return "general";
  for (const p of TOPIC_PATTERNS) {
    if (p.re.test(question)) return p.topic;
  }
  return "general";
}

/** Cheap classifier for watch-listed questions. True = crisis. */
export async function classifyCrisis(aiRun: AiRun, question: string): Promise<boolean> {
  try {
    let out = "";
    for await (const delta of streamDeltas(aiRun, "@cf/meta/llama-3.1-8b-instruct", {
      messages: [
        {
          role: "system",
          content:
            "You are a safety classifier. Reply with exactly YES if the message expresses suicidal ideation, intent to self-harm, or being abused. Reply NO otherwise. No other words.",
        },
        { role: "user", content: question.slice(0, 300) },
      ],
      max_tokens: 4,
    }, 10_000)) {
      out += delta;
      if (out.length > 12) break;
    }
    return /^\s*yes\b/i.test(out);
  } catch {
    return false;
  }
}

/** Supportive reply (no reading). Thai users get the 1323 hotline. */
export function crisisMessage(lang: "th" | "en"): string {
  if (lang === "th") {
    return "\u0e40\u0e07\u0e34\u0e19\u0e44\u0e14\u0e49\u0e22\u0e34\u0e19\u0e04\u0e38\u0e13 \u0e41\u0e25\u0e30\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e19\u0e35\u0e49\u0e2a\u0e33\u0e04\u0e31\u0e0d\u0e01\u0e27\u0e48\u0e32\u0e04\u0e33\u0e17\u0e33\u0e19\u0e32\u0e22\u0e43\u0e14\u0e46 \u0e16\u0e49\u0e32\u0e04\u0e38\u0e13\u0e01\u0e33\u0e25\u0e31\u0e07\u0e04\u0e34\u0e14\u0e17\u0e33\u0e23\u0e49\u0e32\u0e22\u0e15\u0e31\u0e27\u0e40\u0e2d\u0e07\u0e2b\u0e23\u0e37\u0e2d\u0e2d\u0e22\u0e39\u0e48\u0e43\u0e19\u0e20\u0e32\u0e27\u0e30\u0e27\u0e34\u0e01\u0e24\u0e15 \u0e42\u0e1b\u0e23\u0e14\u0e42\u0e17\u0e23\u0e2a\u0e32\u0e22\u0e14\u0e48\u0e27\u0e19\u0e2a\u0e38\u0e02\u0e20\u0e32\u0e1e\u0e08\u0e34\u0e15 1323 (\u0e1f\u0e23\u0e35 \u0e15\u0e25\u0e2d\u0e14 24 \u0e0a\u0e31\u0e48\u0e27\u0e42\u0e21\u0e07) \u0e2b\u0e23\u0e37\u0e2d\u0e1a\u0e2d\u0e01\u0e04\u0e19\u0e17\u0e35\u0e48\u0e04\u0e38\u0e13\u0e44\u0e27\u0e49\u0e43\u0e08\u0e15\u0e2d\u0e19\u0e19\u0e35\u0e49\u0e40\u0e25\u0e22 \u0e04\u0e38\u0e13\u0e44\u0e21\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e40\u0e1c\u0e0a\u0e34\u0e0d\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07\u0e19\u0e35\u0e49\u0e04\u0e19\u0e40\u0e14\u0e35\u0e22\u0e27";
  }
  return "I hear you, and this matters more than any reading. If you are thinking of harming yourself or are in crisis, please contact local emergency services or a crisis line right now, or tell someone you trust. You do not have to face this alone.";
}

// --- Spread picker (server-side, from the question only) ---
//
// The expert spread library is far too large to send on every call, and
// choosing from the cards would let the model flatter the draw. So the
// server picks three position labels from the question + topic alone —
// deterministically, so the same question always yields the same spread
// — and the model must read card N as position N.

type SpreadDef = {
  id: string;
  en: [string, string, string];
  th: [string, string, string];
  test: RegExp;
};

