const GENERAL_SPREAD = {
  id: "general",
  en: ["The situation", "What to handle", "Advice"] as [string, string, string],
  th: ["\u0e2a\u0e16\u0e32\u0e19\u0e01\u0e32\u0e23\u0e13\u0e4c", "\u0e2a\u0e34\u0e48\u0e07\u0e17\u0e35\u0e48\u0e15\u0e49\u0e2d\u0e07\u0e23\u0e31\u0e1a\u0e21\u0e37\u0e2d", "\u0e04\u0e33\u0e41\u0e19\u0e30\u0e19\u0e33"] as [string, string, string],
};
/**
 * Choice-of-2/3 spreads name the options the user wrote
 * ("Tea or coffee?", "should I stay or go", "เทวาลัย vs ทอธ").
 * Question framing around the options is stripped
 * ("Should I ...", "ควร...", "choose between ...", trailing
 * "ไหม / ดี / อันไหน / which is better"). A trailing "not" / "ไหม"
 * fragment means yes/no, not a choice. Returns 2-3 cleaned options
 * (each capped so position labels stay short) or null.
 */
const CHOICE_LEAD_RE = /^(should i|do i|shall i|can i|choose between|buy|get|choose|pick|take|order)\s+|^(\u0e40\u0e25\u0e37\u0e2d\u0e01\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07|\u0e04\u0e27\u0e23|\u0e08\u0e30\u0e40\u0e25\u0e37\u0e2d\u0e01|\u0e0b\u0e37\u0e49\u0e2d|\u0e40\u0e25\u0e37\u0e2d\u0e01|\u0e40\u0e2d\u0e32)\s*/i;
const CHOICE_TAIL_RE = /\s*(which (one )?(is better|should i choose|do you recommend)|\u0e2d\u0e31\u0e19\u0e44\u0e2b\u0e19\u0e14\u0e35|\u0e14\u0e35\u0e01\u0e27\u0e48\u0e32|\u0e14\u0e35\u0e44\u0e2b\u0e21|\u0e44\u0e2b\u0e19\u0e14\u0e35|\u0e2a\u0e33\u0e23\u0e31\u0e1a\u0e44\u0e2b\u0e19|\u0e43\u0e1a\u0e44\u0e2b\u0e19)\??\s*$/i;
const CHOICE_TRAIL_VERB_RE = /^(.+\S)\s+\u0e04\u0e27\u0e23\s*\S+$/i;
const CHOICE_NEG_RE = /^(not|no|\u0e44\u0e2b\u0e21|\u0e2b\u0e23\u0e37\u0e2d\u0e40\u0e1b\u0e25\u0e48\u0e32|\u0e21\u0e31\u0e49\u0e22|\u0e44\u0e21\u0e48)$/i;

function cleanOption(part: string): string {
  return part.trim().replace(/^[“”'"(\[]+|[“”'"\)\].,;:!…?]+$/g, "");
}

export function extractOptions(question: string): string[] | null {
  let q = question.trim().replace(CHOICE_TAIL_RE, "").trim().replace(CHOICE_TRAIL_VERB_RE, "$1").trim();
  for (let n = 0; n < 3; n++) { const next = q.replace(CHOICE_LEAD_RE, "").trim(); if (next === q) break; q = next; }
  let parts: string[] | null = null;
  const vs = q.split(/\s+vs\.?\s+/i).map(cleanOption).filter(Boolean);
  if (vs.length === 2 || vs.length === 3) {
    parts = vs;
  } else {
    const between = q.replace(/^\u0e23\u0e30\u0e2b\u0e27\u0e48\u0e32\u0e07\s+/i, "").split(/\s+\u0e01\u0e31\u0e1a\s+/);
    if (between.length === 2 || between.length === 3) {
      parts = between.map(cleanOption).filter(Boolean);
    } else {
      const orParts = q.split(/(?:\u0e2b\u0e23\u0e37\u0e2d|\s+or\s+)/i).map(cleanOption).filter(Boolean);
      if ((orParts.length === 2 || orParts.length === 3) && !orParts.some((o) => CHOICE_NEG_RE.test(o))) {
        parts = orParts;
      }
    }
  }
  if (!parts || parts.length < 2 || parts.length > 3) return null;
  if (parts.some((o) => CHOICE_NEG_RE.test(o))) return null;
  return parts;
}

function choiceSpread(options: string[], lang: "th" | "en"): [string, string, string] {
  if (options.length >= 3) {
    const [a, b, c] = options;
    return [a, b, c];
  }
  const [a, b] = options;
  return lang === "th"
    ? [`\u0e17\u0e32\u0e07\u0e40\u0e25\u0e37\u0e2d\u0e01 A: ${a}`, "\u0e2b\u0e31\u0e27\u0e43\u0e08\u0e02\u0e2d\u0e07\u0e40\u0e23\u0e37\u0e48\u0e2d\u0e07", `\u0e17\u0e32\u0e07\u0e40\u0e25\u0e37\u0e2d\u0e01 B: ${b}`]
    : [`Option A: ${a}`, "The heart of the matter", `Option B: ${b}`];
}

/** Three position labels chosen from the question + topic alone — never
 *  from the cards. Deterministic: same inputs, same spread. */
export function pickSpread(question: string, topic: Topic, lang: "th" | "en"): [string, string, string] {
  const q = question.toLowerCase();
  const options = extractOptions(question);
  if (options && options.length >= 2) return choiceSpread(options.slice(0, 3), lang);
  for (const s of SPREADS) {
    if (s.id === "relationship" && topic !== "love" && !s.test.test(question)) continue;
    if (s.id === "relationship" && (topic === "career" || topic === "money")) continue;
    if (s.test.test(q) || s.test.test(question)) return lang === "th" ? s.th : s.en;
  }
  if (topic === "love") {
    const s = SPREADS.find((x) => x.id === "relationship")!;
    return lang === "th" ? s.th : s.en;
  }
  return lang === "th" ? GENERAL_SPREAD.th : GENERAL_SPREAD.en;
}

// --- Prompt builder (server builds from D1, never from the client) ---


export type PromptCard = {
  name: string;
  reversed: boolean;
  keywords: string[];
  meaning: string;
  topicNote: string | null;
  imagery: string | null;
};

export type PrevReading = {
  topic: string;
  cardNames: string[];
  summary: string;
};

/**
 * Pick the anchor card deterministically: the card whose own words best
 * match the question. Scores keyword hits against the question plus
 * question-word hits in the card text (either direction counts, since
 * Thai questions often have no spaces to split on). Ties go to the
 * earliest card; with no overlap at all there is no anchor and the
 * prompt falls back to letting the model choose.
 */
export function pickAnchor(question: string, cards: PromptCard[]): string | null {
  const words = question
    .toLowerCase()
    .split(/[^\p{L}\p{N}]+/u)
    .filter((w) => w.length > 1);
  let best: string | null = null;
  let bestScore = 0;
  for (const card of cards) {
    const hayQ = question.toLowerCase();
    const about = `${card.keywords.join(" ")} ${card.meaning}`.toLowerCase();
    let score = 0;
    for (const k of card.keywords) {
      if (k && k.length > 1 && hayQ.includes(k.toLowerCase())) score += 2;
    }
    for (const w of words) {
      if (w && about.includes(w)) score += 1;
    }
    if (score > bestScore) {
      bestScore = score;
      best = card.name;
    }
  }
  return best;
};

export function toPromptCard(card: CardView, reversed: boolean, topic: Topic): PromptCard {
  const topicNote =
    topic === "love" ? card.love :
    topic === "career" ? card.career :
    topic === "money" ? card.money :
    topic === "health" ? card.health : null;
  return {
    // Card names are always written in English (normal for Thai readers).
    name: card.nameEn ?? card.name,
    reversed,
    keywords: reversed ? card.keywordsReversed : card.keywordsUpright,
    meaning: reversed ? card.reversed : card.upright,
    topicNote,
    imagery: card.imagery ?? null,
  };
}

